package com.jejakteknisi.mesh
import android.Manifest;import android.content.Intent;import android.content.pm.PackageManager;import android.os.*;import androidx.activity.ComponentActivity;import androidx.activity.compose.setContent;import androidx.activity.result.contract.ActivityResultContracts;import androidx.compose.foundation.layout.*;import androidx.compose.material3.*;import androidx.compose.runtime.*;import androidx.compose.ui.Alignment;import androidx.compose.ui.Modifier;import androidx.compose.ui.unit.dp;import androidx.core.content.ContextCompat
class MainActivity:ComponentActivity(){private val launcher=registerForActivityResult(ActivityResultContracts.RequestMultiplePermissions()){startIfReady()};override fun onCreate(b:Bundle?){super.onCreate(b);setContent{Screen()};ask()};private fun ask(){val p=mutableListOf<String>();if(ContextCompat.checkSelfPermission(this,Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)p+=Manifest.permission.RECORD_AUDIO;if(Build.VERSION.SDK_INT>=33&&ContextCompat.checkSelfPermission(this,Manifest.permission.NEARBY_WIFI_DEVICES)!=PackageManager.PERMISSION_GRANTED)p+=Manifest.permission.NEARBY_WIFI_DEVICES;if(Build.VERSION.SDK_INT>=33&&ContextCompat.checkSelfPermission(this,Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)p+=Manifest.permission.POST_NOTIFICATIONS;if(p.isEmpty())startIfReady()else launcher.launch(p.toTypedArray())};private fun startIfReady(){if(ContextCompat.checkSelfPermission(this,Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED)ContextCompat.startForegroundService(this,Intent(this,IntercomService::class.java))}}
@Composable fun Screen(){var s by remember{mutableStateOf(IntercomService.engine?.status?:"Menyiapkan Wi-Fi Direct...")};DisposableEffect(Unit){IntercomService.engine?.onStatus={s=it};onDispose{IntercomService.engine?.onStatus=null}};MaterialTheme{Surface(Modifier.fillMaxSize()){Column(Modifier.fillMaxSize().padding(20.dp),horizontalAlignment=Alignment.CenterHorizontally){Text("JEJAK TEKNISI",style=MaterialTheme.typography.headlineMedium);Text("MESH INTERCOM V1.6",style=MaterialTheme.typography.titleMedium);Spacer(Modifier.height(20.dp));Card(Modifier.fillMaxWidth()){Column(Modifier.padding(20.dp)){Text(s,style=MaterialTheme.typography.titleLarge);Spacer(Modifier.height(8.dp));Text("Mode: WI-FI DIRECT");Text("2 HP tanpa router / tanpa Wi-Fi yang sama")}};Spacer(Modifier.weight(1f));Button(onClick={IntercomService.engine?.connectToFirstPeer()},modifier=Modifier.fillMaxWidth()){Text("CARI & HUBUNGKAN")}}}}}
